<script setup lang="ts">
import { computed } from 'vue'
import AppIcon from './AppIcon.vue'
import { useStudyStore } from '../domain/store'

const emit = defineEmits<{ (event: 'open-question', id: string): void; (event: 'practice', ids: string[]): void }>()
const store = useStudyStore()
const stats = computed(() => store.stats.value)
const questions = computed(() => store.readyQuestions.value)
const masteryRate = computed(() => stats.value.ready ? Math.round(stats.value.mastered / stats.value.ready * 100) : 0)
const weekly = computed(() => stats.value.weeklyHistory)
const weeklyTotal = computed(() => weekly.value.reduce((total, day) => total + day.reviewed, 0))
const chartMaximum = computed(() => Math.max(1, ...weekly.value.map(day => day.reviewed)))
const subjectCounts = computed(() => stats.value.subjectCounts.filter(item => item.total > 0))
const subjectMaximum = computed(() => Math.max(1, ...subjectCounts.value.map(item => item.total)))
const difficultyDistribution = computed(() => {
  const levels = [
    { name: '基础', color: '#91aa78' },
    { name: '进阶', color: '#d0a063' },
    { name: '挑战', color: '#9b88af' },
  ] as const
  return levels.map(level => {
    const count = questions.value.filter(question => question.difficulty === level.name).length
    return { ...level, count, percentage: Math.round(count / Math.max(1, questions.value.length) * 100) }
  })
})
const currentWeekDays = computed(() => weekly.value.filter(day => day.reviewed > 0).length)
const weakSubject = computed(() => [...stats.value.subjectCounts].filter(item => item.reinforce > 0).sort((a, b) => b.reinforce - a.reinforce)[0])
const weakSubjectIds = computed(() => questions.value.filter(question => question.subject === weakSubject.value?.subject && question.status !== 'mastered').map(question => question.id))
const reviewSubtitle = computed(() => stats.value.reviewCount > 0 ? `${stats.value.reviewCount} 次有效自评记录` : '完成一次复习后开始统计')

function barHeight(count: number) { return `${count ? Math.max(9, count / chartMaximum.value * 128) : 3}px` }
function subjectColor(index: number) { return ['#39775a', '#91aa78', '#e5a863', '#a3b6ac', '#b6b08b', '#83a29b'][index % 6] }
</script>

<template>
  <view class="insights-view">
    <view class="insights-heading"><view><text class="eyebrow">SMALL STEPS, REAL PROGRESS</text><text class="insights-title">进步，都有迹可循。</text><text class="muted insights-description">看见薄弱点，也看见每一次巩固的积累。</text></view><view class="data-tag"><view class="live-dot" /><text>随学习记录更新</text></view></view>

    <view class="insight-metrics">
      <view class="metric-card panel"><view class="metric-top"><text>收录错题</text><view class="metric-icon"><AppIcon name="layers" :size="18" tone="green" /></view></view><view class="metric-number-row"><text class="metric-number">{{ stats.total }}</text><text class="metric-unit">道</text></view><text class="metric-footnote">{{ stats.pending }} 道待处理 · {{ stats.ready }} 道已整理</text></view>
      <view class="metric-card panel"><view class="metric-top"><text>自评正确率</text><view class="metric-icon metric-icon-orange"><AppIcon name="target" :size="18" tone="orange" /></view></view><view class="metric-number-row"><text class="metric-number">{{ stats.reviewCount ? Math.round(stats.accuracy) : '—' }}</text><text class="metric-unit">{{ stats.reviewCount ? '%' : '' }}</text></view><text class="metric-footnote">{{ reviewSubtitle }}</text></view>
      <view class="metric-card panel"><view class="metric-top"><text>连续复习</text><view class="metric-icon"><AppIcon name="flame" :size="18" tone="green" /></view></view><view class="metric-number-row"><text class="metric-number">{{ stats.streak }}</text><text class="metric-unit">天</text></view><text class="metric-footnote">今天已完成 {{ stats.todayReviewCount }} 次复习</text></view>
      <view class="metric-card panel"><view class="metric-top"><text>知识沉淀</text><view class="metric-icon metric-icon-soft"><AppIcon name="book-open" :size="18" tone="green" /></view></view><view class="metric-number-row"><text class="metric-number">{{ store.notes.value.length }}</text><text class="metric-unit">篇</text></view><text class="metric-footnote">把解题经验留在知识笔记里</text></view>
    </view>

    <view class="insight-main-grid">
      <view class="activity-panel panel"><view class="chart-heading"><view><text class="section-title">这一周的小坚持</text><text class="chart-description">近 7 天复习次数</text></view><view class="chart-total"><text>{{ weeklyTotal }}</text><text>次复习</text></view></view>
        <view class="weekly-chart"><view class="chart-gridline gridline-top" /><view class="chart-gridline gridline-middle" /><view class="chart-gridline gridline-bottom" /><view v-for="(day, index) in weekly" :key="day.date" class="day-column"><text class="bar-value">{{ day.reviewed }}</text><view class="bar-area"><view class="day-bar" :class="{ 'day-bar-today': index === weekly.length - 1, 'day-bar-empty': day.reviewed === 0 }" :style="{ height: barHeight(day.reviewed) }" /></view><text class="day-label" :class="{ 'day-label-today': index === weekly.length - 1 }">{{ index === weekly.length - 1 ? '今天' : day.label }}</text></view></view>
        <view class="chart-footer"><view class="chart-legend"><view class="legend-dot" /><text>单题复习与在线练习</text></view><text>本周已学习 {{ currentWeekDays }} 天</text></view>
      </view>

      <view class="mastery-panel panel"><view class="chart-heading"><view><text class="section-title">离掌握更近一点</text><text class="chart-description">已整理题目的掌握状态</text></view><AppIcon name="sparkles" :size="19" tone="orange" /></view><view class="mastery-content"><view class="mastery-ring" :style="{ background: `conic-gradient(#39775a 0deg ${masteryRate * 3.6}deg, #edf1e9 ${masteryRate * 3.6}deg 360deg)` }"><view class="mastery-ring-center"><view><text class="mastery-percentage">{{ masteryRate }}</text><text class="mastery-percent-sign">%</text></view><text class="mastery-label">掌握率</text></view></view><view class="mastery-breakdown"><view><view class="legend-dot" /><text>已掌握</text><text class="mastery-count">{{ stats.mastered }}</text></view><view><view class="legend-dot legend-dot-soft" /><text>待巩固</text><text class="mastery-count">{{ stats.reinforce }}</text></view></view></view><text class="mastery-hint">{{ stats.ready ? '每一次重新做对，都在让这只圆环更完整。' : '收录错题后，在这里查看你的掌握进度。' }}</text></view>
    </view>

    <view class="insight-bottom-grid">
      <view class="subject-panel panel"><view class="chart-heading"><view><text class="section-title">学科分布</text><text class="chart-description">每一科，都有自己的节奏</text></view><text class="small-count">{{ subjectCounts.length }} 个学科</text></view><view v-if="subjectCounts.length" class="subject-chart"><view v-for="(item, index) in subjectCounts" :key="item.subject" class="subject-row"><view class="subject-label"><view class="subject-color-dot" :style="{ background: subjectColor(index) }" /><text>{{ item.subject }}</text></view><view class="subject-bar-track"><view class="subject-bar-fill" :style="{ width: `${item.total / subjectMaximum * 100}%`, background: subjectColor(index) }" /></view><view class="subject-numbers"><text>{{ item.total }}</text><text>道</text></view></view></view><view v-else class="chart-empty"><AppIcon name="chart-no-axes-combined" :size="28" tone="muted" /><text>收录第一道错题，学科分布就会出现在这里。</text></view><view v-if="weakSubject" class="weak-subject-tip"><AppIcon name="arrow-up-right" :size="16" tone="green" /><text>{{ weakSubject.subject }}还有 {{ weakSubject.reinforce }} 道待巩固</text><button class="start-practice" @click="emit('practice', weakSubjectIds)">去巩固<AppIcon name="chevron-right" :size="13" tone="green" /></button></view></view>

      <view class="difficulty-panel panel"><view class="chart-heading"><view><text class="section-title">题目难度分布</text><text class="chart-description">从基础到挑战，循序渐进地练习</text></view><AppIcon name="chart-column" :size="19" tone="muted" /></view><view v-if="questions.length" class="difficulty-list"><view v-for="(item, index) in difficultyDistribution" :key="item.name" class="difficulty-row"><view class="difficulty-level" :style="{ color: item.color }">{{ String(index + 1).padStart(2, '0') }}</view><view class="difficulty-body"><view class="difficulty-label-row"><text class="difficulty-name">{{ item.name }}</text><text class="difficulty-count">{{ item.count }} 道<text class="difficulty-percentage">{{ item.percentage }}%</text></text></view><view class="difficulty-bar-track"><view class="difficulty-bar-fill" :style="{ width: `${item.percentage}%`, background: item.color }" /></view></view></view></view><view v-else class="chart-empty"><AppIcon name="chart-column" :size="28" tone="muted" /><text>收录题目并设置难度后，在这里查看分布。</text></view><text class="difficulty-footnote">难度沿用题目的当前设置，可在编辑题目时调整。</text></view>
    </view>
    <view class="statistics-note"><AppIcon name="info" :size="14" tone="muted" /><text>收录总数包含待处理题；学科、难度、掌握率与复习统计仅包含未删除的已整理题目。自评正确率按有效复习记录计算，“已掌握”自评计为正确。</text></view>
  </view>
</template>

<style scoped>
